1	<title>Nxeon Hosting — Restructure Blueprint</title>
2	<style>
3	  :root{
4	    --ground:#070b16; --ground2:#0b1020; --panel:#0f152a; --panel2:#131a33; --hi:#182142;
5	    --line:rgba(255,255,255,.08); --line2:rgba(255,255,255,.14);
6	    --text:#eef1fb; --muted:#9aa4c2; --faint:#6a7590;
7	    --violet:#8b5cf6; --violet2:#a78bfa; --cyan:#22d3ee; --emerald:#34d399; --amber:#fbbf24;
8	    --grad:linear-gradient(120deg,#8b5cf6,#22d3ee);
9	    --sans:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
10	    --mono:ui-monospace,"SF Mono","JetBrains Mono",monospace;
11	  }
12	  *{box-sizing:border-box;margin:0;padding:0}
13	  body{font-family:var(--sans);color:var(--text);background:var(--ground);line-height:1.6;
14	    background-image:radial-gradient(60rem 44rem at 88% -10%,rgba(139,92,246,.12),transparent 60%),radial-gradient(46rem 40rem at 0% 4%,rgba(34,211,238,.08),transparent 55%);}
15	  .wrap{max-width:940px;margin:0 auto;padding:56px 26px 90px}
16	  .eyebrow{font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:var(--violet2);font-weight:700}
17	  h1{font-size:clamp(30px,5vw,46px);letter-spacing:-.025em;line-height:1.08;margin:14px 0 12px;text-wrap:balance}
18	  h1 .g{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
19	  .sub{font-size:18px;color:var(--muted);max-width:60ch}
20	  h2{font-size:23px;letter-spacing:-.02em;margin:0 0 4px;display:flex;align-items:center;gap:12px}
21	  h2 .n{width:30px;height:30px;border-radius:9px;background:var(--hi);border:1px solid var(--line2);display:grid;place-items:center;font-size:14px;font-weight:800;color:var(--violet2);flex:none}
22	  section{margin-top:52px}
23	  .lead{color:var(--muted);margin:10px 0 20px;max-width:64ch}
24	  .card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px 24px}
25	  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
26	  @media(max-width:720px){.grid2{grid-template-columns:1fr}}
27	  .ba{display:grid;grid-template-columns:1fr auto 1fr;gap:16px;align-items:center}
28	  @media(max-width:720px){.ba{grid-template-columns:1fr}.ba .arrow{transform:rotate(90deg);justify-self:center}}
29	  .ba .arrow{color:var(--violet2);font-size:26px}
30	  .tag{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.03em;padding:3px 9px;border-radius:99px;margin-bottom:10px}
31	  .tag.old{color:#fca5a5;background:rgba(248,113,113,.1);border:1px solid rgba(248,113,113,.28)}
32	  .tag.new{color:var(--emerald);background:rgba(52,211,153,.1);border:1px solid rgba(52,211,153,.28)}
33	  .card h4{font-size:15px;margin-bottom:8px}
34	  .card p,.card li{color:var(--muted);font-size:14.5px}
35	  ul{margin:8px 0 0 18px}li{margin:4px 0}
36	  .mono{font-family:var(--mono);font-size:13px;color:var(--cyan)}
37	  .ent{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-top:8px}
38	  .ent .e{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:14px}
39	  .ent .e b{font-size:14px;display:block;margin-bottom:5px}
40	  .ent .e.key{border-color:rgba(139,92,246,.4);box-shadow:inset 0 0 0 1px rgba(139,92,246,.12)}
41	  .ent .e span{font-size:12.5px;color:var(--faint)}
42	  pre.dia{background:var(--ground2);border:1px solid var(--line);border-radius:12px;padding:16px;overflow-x:auto;font-family:var(--mono);font-size:12.5px;color:var(--muted);line-height:1.5}
43	  pre.dia b{color:var(--violet2)}pre.dia i{color:var(--cyan);font-style:normal}
44	  .flow{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:6px}
45	  .flow .s{background:var(--panel2);border:1px solid var(--line2);border-radius:10px;padding:8px 13px;font-size:13.5px}
46	  .flow .a{color:var(--faint)}
47	  .flow .s b{color:var(--violet2)}
48	  table{width:100%;border-collapse:collapse;margin-top:10px;font-size:14px}
49	  th,td{text-align:left;padding:11px 12px;border-bottom:1px solid var(--line)}
50	  th{color:var(--faint);font-size:11.5px;text-transform:uppercase;letter-spacing:.08em}
51	  td b{color:var(--text)}td{color:var(--muted)}
52	  .phase{border-left:2px solid var(--line2);padding:2px 0 2px 20px;position:relative;margin:0 0 18px}
53	  .phase::before{content:"";position:absolute;left:-6px;top:6px;width:10px;height:10px;border-radius:50%;background:var(--grad)}
54	  .phase h4{font-size:15.5px}.phase.p1::before{background:var(--emerald)}
55	  .pill{font-size:11px;font-weight:700;padding:2px 8px;border-radius:99px;border:1px solid var(--line2);color:var(--muted)}
56	  .q{background:linear-gradient(180deg,rgba(139,92,246,.08),transparent);border:1px solid rgba(139,92,246,.25);border-radius:14px;padding:18px 20px;margin-top:12px}
57	  .q b{color:var(--violet2)}
58	  .foot{margin-top:60px;color:var(--faint);font-size:13px;border-top:1px solid var(--line);padding-top:18px}
59	  strong{color:var(--text)}
60	</style>
