1	"use client";
2	/* eslint-disable @next/next/no-img-element */
3	
4	import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
5	import {
6	  getHostingAccount,
7	  revealHostingSftpPassword,
8	  recheckHostingHealth,
9	  renameHostingAccount,
10	  listWebsites,
11	  listHostingDatabases,
12	  listHostingBackups,
13	  listHostingSubdomains,
14	  listHostingAddonDomains,
15	  listHostingTaskLog,
16	  installWordPress,
17	  installApp,
18	  listAppCatalog,
19	  setPrimaryHostingDomain,
20	  deleteSubdomain,
21	  deleteAddonDomain,
22	  createFreeSubdomainSite,
23	  createAddonDomain,
24	  checkHostingSubdomain,
25	  removeHostingThumbnail,
26	  type HostingAccountView,
27	  type HostingWebsiteView,
28	  type SiteTarget,
29	} from "@/lib/actions-hosting";
30	import { getHostingEmailStatus } from "@/lib/hosting-email";
31	import { Badge, StatCard, StatusDot, fmtBytes, timeAgo } from "@/components/ui/primitives";
32	import { Icon, type IconName } from "@/components/ui/Icon";
33	import { AppLogo } from "@/components/ui/AppLogo";
34	import { QuotaTile } from "./shared";
35	import { AppCredentials } from "./AppCredentials";
36	import { FileManager } from "./FileManager";
37	import { Backups } from "./Backups";
38	import { DatabasesPanel } from "./DatabasesPanel";
39	import { PhpSwitcher } from "./PhpSwitcher";
40	import { SubdomainsPanel } from "./SubdomainsPanel";
41	import { AddonDomainsPanel } from "./AddonDomainsPanel";
42	import { CronPanel } from "./CronPanel";
43	import { EmailTab } from "./EmailTab";
44	import { HostingUpgradePanel } from "./HostingUpgradePanel";
45	
46	/* ==========================================================================
47	 * Hosting console — the plan-as-workspace shell, rebuilt on the portal's real
48	 * design system (components/ui/primitives + Icon + AppLogo + the global .card/.btn
49	 * utility classes). NO emojis anywhere: every glyph is an inline-SVG <Icon> or a
50	 * brand <AppLogo>.
51	 *
52	 * Two views, both URL-addressable so links survive a refresh:
53	 *   • PLAN CONSOLE (default)  — header + resource stat-cards (primary nav) + a
54	 *     website GRID whose cards carry a real thumbnail/preview + Activity / Plan /
55	 *     Usage. Plan-scoped SECTIONS (Databases, Email, Backups, Domains, Files, Cron,
56	 *     Logs, Settings) reuse the existing panels verbatim.  URL: `?tab=<section>`.
57	 *   • WEBSITE DETAIL          — scoped to ONE website, a fully self-contained site
58	 *     (its own domain, app, files, SSL, stats) with NO primary-centric framing.
59	 *     URL: `?site=<id|primary>&stab=<subtab>`.
60	 *
61	 * Every read/mutation is a real ownership-guarded server action — no mock data.
62	 * ======================================================================== */
63	
64	const SECTIONS: [key: string, label: string, icon: IconName][] = [
65	  ["databases", "Databases", "database"],
66	  ["email", "Email", "mail"],
67	  ["backups", "Backups", "clock"],
68	  ["domains", "Domains & SSL", "globe"],
69	  ["files", "File Manager", "folder"],
70	  ["cron", "Cron", "refresh"],
71	  ["logs", "Logs", "activity"],
72	  ["settings", "Settings", "settings"],
73	];
74	const SECTION_KEYS = SECTIONS.map(([k]) => k);
75	
76	const SITE_TABS: [key: string, label: string][] = [
77	  ["overview", "Overview"],
78	  ["app", "App"],
79	  ["files", "Files"],
80	  ["domains", "Domains & SSL"],
81	  ["email", "Email"],
82	  ["databases", "Databases"],
83	  ["logs", "Logs"],
84	  ["settings", "Settings"],
85	];
86	const SITE_TAB_KEYS = SITE_TABS.map(([k]) => k);
87	
88	type Counts = {
89	  dbs: number;
90	  backups: number;
91	  emailUsed: number;
92	  emailCap: number | null;
93	  subs: number;
94	  addons: number;
95	};
96	
97	/* ---- app-visual mapping: an installed-app label → a brand logo or a clean icon --- */
98	
99	const APP_LOGO_MATCHERS: [needle: string, family: string][] = [
100	  ["woocommerce", "woocommerce"],
101	  ["wordpress", "wordpress"],
102	  ["ghost", "ghost"],
103	  ["nextcloud", "nextcloud"],
104	  ["gitea", "gitea"],
105	  ["grafana", "grafana"],
106	  ["jellyfin", "jellyfin"],
107	  ["portainer", "portainer"],
108	];
109	
110	function appVisual(installedApp: string | null): { logo?: string; icon: IconName } {
111	  const s = (installedApp ?? "").toLowerCase();
112	  if (!s) return { icon: "globe" }; // static site / no app
113	  for (const [needle, family] of APP_LOGO_MATCHERS) if (s.includes(needle)) return { logo: family, icon: "grid" };
114	  return { icon: "grid" };
115	}
116	
117	/** A square app badge: the real brand logo when known, else a tasteful icon chip. */
118	function AppBadge({ installedApp, size = 32 }: { installedApp: string | null; size?: number }) {
119	  const v = appVisual(installedApp);
120	  if (v.logo) return <AppLogo family={v.logo} name={installedApp ?? undefined} size={size} />;
121	  return (
122	    <span
123	      className="flex items-center justify-center rounded-lg border border-white/10 bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-200"
124	      style={{ width: size, height: size, minWidth: size }}
125	    >
126	      <Icon name={v.icon} size={Math.round(size * 0.52)} />
127	    </span>
128	  );
129	}
130	
131	/** A website's thumbnail: the customer's uploaded preview, or a branded placeholder
132	 *  (subtle gradient + app logo + hostname — never an emoji). */
133	function Thumbnail({ accountId, site }: { accountId: string; site: HostingWebsiteView }) {
134	  if (site.thumbnailAt) {
135	    const src = `/api/hosting/${accountId}/thumbnail?site=${encodeURIComponent(site.key)}&v=${encodeURIComponent(site.thumbnailAt)}`;
136	    return <img src={src} alt={`${site.hostname} preview`} className="h-full w-full object-cover" />;
137	  }
138	  return (
139	    <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-gradient-to-br from-navy-900 via-brand-500/10 to-accent-blue/20">
140	      <div
141	        className="absolute inset-0 opacity-[0.12]"
142	        style={{ backgroundImage: "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.6) 1px, transparent 0)", backgroundSize: "16px 16px" }}
143	      />
144	      <div className="relative flex flex-col items-center gap-2 px-3 text-center">
145	        <AppBadge installedApp={site.installedApp} size={40} />
146	        <span className="max-w-full truncate font-mono text-xs text-slate-300">{site.hostname}</span>
147	      </div>
148	    </div>
149	  );
150	}
151	
152	export function HostingConsole({
153	  account,
154	  initialTab,
155	  initialPath,
156	  initialSite,
157	  initialSiteTab,
158	}: {
159	  account: HostingAccountView;
160	  initialTab?: string;
161	  initialPath?: string;
162	  initialSite?: string;
163	  initialSiteTab?: string;
164	}) {
165	  const active = account.status === "ACTIVE";
166	
167	  const [siteParam, setSiteParam] = useState<string | undefined>(initialSite);
168	  const [siteTab, setSiteTab] = useState<string>(
169	    initialSiteTab && SITE_TAB_KEYS.includes(initialSiteTab) ? initialSiteTab : "overview",
170	  );
171	  const [section, setSection] = useState<string>(
172	    initialTab && SECTION_KEYS.includes(initialTab) ? initialTab : "console",
173	  );
174	
175	  const [sites, setSites] = useState<HostingWebsiteView[] | null>(null);
176	  const refreshSites = useCallback(() => {
177	    if (!active) { setSites([]); return; }
178	    listWebsites(account.id).then(setSites).catch(() => setSites([]));
179	  }, [account.id, active]);
180	  useEffect(() => { refreshSites(); }, [refreshSites]);
181	
182	  function pushUrl(params: Record<string, string | undefined>) {
183	    const qs = new URLSearchParams();
184	    for (const [k, v] of Object.entries(params)) if (v) qs.set(k, v);
185	    const s = qs.toString();
186	    window.history.replaceState(null, "", s ? `?${s}` : window.location.pathname);
187	  }
