942	function DnsStepper({ account }: { account: HostingAccountView }) {
943	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
944	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
945	  const verified = account.sslActive && account.serveHttpsOk !== false;
946	  const state: "verified" | "issuing" | "dns" | "pending" = verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
947	  const free = account.isFreeSubdomain;
948	  const steps = [
949	    { label: free ? "DNS ready" : "Point domain", done: true },
950	    { label: "Site live", done: state === "issuing" || state === "verified" },
951	    { label: "HTTPS verified", done: state === "verified" },
952	  ];
953	  const headline =
954	    account.healthNote ??
955	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
956	  const tone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
957	  return (
958	    <div>
959	      <div className="flex items-center">
960	        {steps.map((s, i) => (
961	          <div key={s.label} className="flex flex-1 items-center last:flex-none">
962	            <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
963	              {s.done ? <Icon name="check" size={13} /> : i + 1}
964	            </span>
965	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
966	          </div>
967	        ))}
968	      </div>
969	      <div className="mt-1.5 flex items-start justify-between text-[11px]">
970	        {steps.map((s) => (
971	          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
972	            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
973	          </div>
974	        ))}
975	      </div>
976	      <p className={`mt-2 text-xs font-medium ${tone}`}>{headline}</p>
977	    </div>
978	  );
979	}
