137	/** The ordered list of hosts the account may host mail on, tagged with their kind. */
138	function accountDomains(a: AccountWithDomains): { host: string; kind: DomainKind }[] {
139	  const out: { host: string; kind: DomainKind }[] = [
140	    { host: normalizeDomain(a.primaryDomain), kind: "primary" },
141	  ];
142	  for (const s of a.subdomains) out.push({ host: normalizeDomain(s.fqdn), kind: "subdomain" });
143	  for (const d of a.addonDomains) out.push({ host: normalizeDomain(d.domain), kind: "addon" });
144	  // De-dupe defensively (a promoted addon can equal the primary for a moment).
145	  const seen = new Set<string>();
146	  return out.filter((o) => o.host && !seen.has(o.host) && seen.add(o.host));
