161	export async function getHostingEmailStatus(accountId: string): Promise<HostingEmailStatus> {
162	  const user = await requireUser();
163	
164	  const account = await loadAccount(accountId);
165	  if (!account) return { error: "Not found." };
166	  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
167	
168	  const domains = accountDomains(account);
169	  const hosts = domains.map((d) => d.host);
170	
171	  // Every non-cancelled subscription touching any of the account's domains — used
172	  // for the global-dedup availability flags AND to locate the bundled subscription.
173	  const subs = hosts.length
174	    ? await db.emailSubscription.findMany({
175	        where: { domainName: { in: hosts }, status: { not: "CANCELLED" } },
176	        include: { emailPlan: true, mailboxes: true },
177	      })
178	    : [];
