180	  // The bundled subscription: preferably the one explicitly linked to this account;
181	  // otherwise a pre-existing bundled row (bundled plan on the primary domain, no
182	  // link) which we self-heal by adopting the link now (back-compat migration).
183	  let bundledSub =
