239	  return {
240	    planName: account.plan.name,
241	    includedMailboxes: account.plan.mailboxes,
242	    primaryDomain: normalizeDomain(account.primaryDomain),
243	    domainOptions,
244	    bundled,
245	    hasSubscription: !!bundled,
