264	/**
265	 * Shared guard for the two mutations: validate the chosen domain is one of the
266	 * account's, is well-formed, and free of the global one-subscription-per-domain
267	 * conflict. Takes an already-owned account. Returns the resolved domain + kind.
268	 */
269	async function resolveTargetDomain(
270	  account: AccountWithDomains,
271	  domainNameRaw: string,
272	  opts: { ignoreSubscriptionId?: string } = {},
273	): Promise<
274	  | { error: string }
275	  | { domain: string; kind: DomainKind; free: boolean }
276	> {
277	  const domain = normalizeDomain(domainNameRaw);
278	  if (!domain) return { error: "Choose a domain for your email." };
279	
280	  const options = accountDomains(account);
281	  const match = options.find((o) => o.host === domain);
282	  if (!match) {
283	    return { error: "That domain isn't on this hosting account. Add it in the Domains tab first." };
284	  }
285	  // Free subdomains legitimately aren't registrable-domain shaped; only validate the
286	  // shape of real domains.
287	  const free = isFreeSubdomain(domain);
288	  if (!free && !domainRe.test(domain)) {
289	    return { error: "That doesn't look like a valid domain." };
290	  }
291	
292	  // GLOBAL domain dedup — one subscription per domain across ALL users.
293	  const dupe = await db.emailSubscription.findFirst({
294	    where: { domainName: domain, status: { not: "CANCELLED" } },
295	  });
296	  if (dupe && dupe.id !== opts.ignoreSubscriptionId) {
297	    if (dupe.userId !== account.userId) {
298	      return {
299	        error:
300	          "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
301	      };
302	    }
303	    // Owned by this customer already (e.g. a separate paid Business Email order, or
304	    // the bundled sub itself when it's not the one we're ignoring).
305	    return { error: "This domain already has email. Manage it from the email dashboard." };
306	  }
307	
308	  return { domain, kind: match.kind, free };
309	}
