349	  // Single bundled subscription per account. If one already exists, only a no-op on
350	  // the same domain is allowed here; moving domains goes through changeHostingEmailDomain.
351	  const existing = await db.emailSubscription.findFirst({
352	    where: { hostingAccountId: account.id, status: { not: "CANCELLED" } },
353	  });
354	  if (existing) {
355	    if (existing.domainName === normalizeDomain(domainName)) {
356	      return { ok: true, subscriptionId: existing.id };
357	    }
358	    return {
359	      error: `Bundled email is already set up on ${existing.domainName}. Move it to change the domain.`,
360	    };
361	  }
362	
363	  const resolved = await resolveTargetDomain(account, domainName);
364	  if ("error" in resolved) return { error: resolved.error };
365	  const { domain, free } = resolved;
366	
367	  const plan = await findBundledPlan(account.plan.mailboxes);
368	  if (!plan) {
369	    return {
370	      error:
371	        "Bundled email isn't configured for this plan yet. Please contact support — no charge, we'll switch it on.",
372	    };
373	  }
374	
375	  const sub = await db.emailSubscription.create({
376	    data: {
377	      userId: account.userId,
378	      hostingAccountId: account.id,
379	      domainName: domain,
380	      emailPlanId: plan.id,
381	      status: "ACTIVE",
382	      autoRenew: true,
383	      expiresAt: account.expiresAt,
384	      // Free subdomain → we own the zone: managed + verified now (like an in-account
385	      // domain), records auto-published below. Real domain → external + unverified
386	      // until the customer publishes DNS and we confirm it.
387	      external: !free,
388	      verified: free,
389	      verifiedAt: free ? new Date() : null,
390	      verifyToken: free ? null : randomBytes(24).toString("hex"),
391	    },
392	  });
393	
394	  await db.auditLog
395	    .create({
396	      data: {
397	        userId: account.userId,
398	        action: "hostingemail.setup",
399	        detail: `${domain} · bundled ${plan.name} (${plan.mailboxes} mailbox${plan.mailboxes === 1 ? "" : "es"}) via hosting ${account.plan.name}`,
400	      },
401	    })
402	    .catch(() => {});
403	
404	  if (free) await autoConfigureFreeSubdomain(account.userId, domain);
405	
406	  revalidatePath(`/dashboard/hosting/${accountId}`);
407	  revalidatePath("/dashboard/email");
408	  return { ok: true, subscriptionId: sub.id };
409	}
