411	/**
412	 * Move the account's bundled email to a different domain on the account. Owner or
413	 * admin; blocked while impersonating. Refused while the current bundled domain has
414	 * mailboxes — those are keyed to the old address on the mail server, so moving the
415	 * domain out from under them would orphan live mail. Remove the mailboxes first.
416	 */
417	export async function changeHostingEmailDomain(
418	  accountId: string,
419	  domainName: string,
420	): Promise<HostingEmailResult> {
421	  await requireUser();
422	  await assertNotImpersonating();
423	
424	  const owned = await ownedAccount(accountId);
425	  if ("error" in owned) return { error: owned.error };
426	  const { account } = owned;
427	
428	  const bundled = await db.emailSubscription.findFirst({
429	    where: { hostingAccountId: account.id, status: { not: "CANCELLED" } },
430	    include: { mailboxes: { select: { id: true } } },
431	  });
432	  if (!bundled) return { error: "Set up bundled email first, then you can change its domain." };
433	
434	  const resolved = await resolveTargetDomain(account, domainName, {
435	    ignoreSubscriptionId: bundled.id,
436	  });
437	  if ("error" in resolved) return { error: resolved.error };
438	  const { domain, free } = resolved;
439	
440	  if (bundled.domainName === domain) return { ok: true, subscriptionId: bundled.id };
441	
442	  if (bundled.mailboxes.length > 0) {
443	    return {
444	      error: `Remove the ${bundled.mailboxes.length} mailbox${bundled.mailboxes.length === 1 ? "" : "es"} on ${bundled.domainName} before moving email to another domain.`,
445	    };
446	  }
447	
448	  await db.emailSubscription.update({
449	    where: { id: bundled.id },
450	    data: {
451	      domainName: domain,
452	      external: !free,
453	      verified: free,
454	      verifiedAt: free ? new Date() : null,
455	      verifyToken: free ? null : randomBytes(24).toString("hex"),
456	      // Drop the cached DKIM from the old domain — it belongs to the old zone.
457	      dkimRecord: null,
458	    },
459	  });
460	
461	  await db.auditLog
462	    .create({
463	      data: {
464	        userId: account.userId,
465	        action: "hostingemail.movedomain",
466	        detail: `${bundled.domainName} → ${domain}`,
467	      },
468	    })
469	    .catch(() => {});
470	
471	  if (free) await autoConfigureFreeSubdomain(account.userId, domain);
472	
473	  revalidatePath(`/dashboard/hosting/${accountId}`);
474	  revalidatePath("/dashboard/email");
475	  return { ok: true, subscriptionId: bundled.id };
476	}
