export type HostingEmailStatus = {
  error?: string;
  planName?: string;
  includedMailboxes?: number;
  primaryDomain?: string;
  /** Every domain on the account the customer may attach mail to. */
  domainOptions?: HostingMailDomainOption[];
  /** The current bundled mail domain + its mailboxes, or null if not set up yet. */
  bundled?: HostingBundledEmail | null;
  /** Convenience flag the UI can gate on. */
  hasSubscription?: boolean;
};

/**
 * THE FLEXIBLE MAILBOX POOL (website-first restructure, Phase 1).
 *
 * The plan unlocks N mailboxes; the customer spreads them across ANY of their
 * domains — 5 on shop.com, 3 on blog.com — instead of every mailbox being pinned
 * to one domain. Mechanically, each domain the customer puts mail on gets its own
 * bundled EmailSubscription (all linked by `hostingAccountId`), and the shared cap
 * `poolCap` = plan.mailboxes is enforced against the SUM of mailboxes across every
 * one of those subscriptions (see addHostingPoolMailbox) — so spreading mail over
 * several domains can never multiply the entitlement.
 */
export type HostingEmailPool = {
  error?: string;
  planName?: string;
  /** plan.mailboxes — the total the customer may allocate across all domains. */
  poolCap?: number;
  /** Mailboxes currently allocated across every domain (the pool's used count). */
  poolUsed?: number;
  primaryDomain?: string;
  /** Every domain on the account, with attach-availability flags (for "add on a
   *  new domain" picker). */
  domainOptions?: HostingMailDomainOption[];
  /** One entry per domain that currently hosts mail, with its mailboxes + DNS state. */
  mailDomains?: HostingBundledEmail[];
};

export type HostingPoolMailboxResult = { ok?: boolean; error?: string; subscriptionId?: string };

import { isFreeSubdomain } from "./hosting";
import { provisionFreeSubdomainMailDns } from "./mail/platform-dns";
// The pool add path delegates the actual mailbox creation (Mailcow provisioning,
// address validation, per-subscription verify gate) to the audited addMailbox so
// none of that logic is duplicated; the wrapper adds only the cross-domain pool cap.
import { addMailbox } from "./actions-email-hosting";

