/* ========================================================================== *
 *  FLEXIBLE MAILBOX POOL — allocate the plan's mailboxes across ANY domains.  *
 * ========================================================================== */

/** Shape one bundled subscription (a mail-hosting domain) into the view type. */
function toBundledView(
  account: AccountWithDomains,
  sub: {
    id: string;
    domainName: string;
    external: boolean;
    verified: boolean;
    status: string;
    emailPlan: { mailboxes: number };
    mailboxes: { id: string; address: string; status: string; createdAt: Date }[];
  },
): HostingBundledEmail {
  return {
    subscriptionId: sub.id,
    domainName: sub.domainName,
    kind: kindOf(account, sub.domainName),
    free: isFreeSubdomain(sub.domainName),
    external: sub.external,
    verified: sub.verified,
    status: sub.status,
    mailboxCap: sub.emailPlan.mailboxes,
    mailboxes: sub.mailboxes
      .slice()
      .sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime())
      .map((m) => ({ id: m.id, address: m.address, status: m.status, createdAt: m.createdAt.toISOString() })),
  };
}

/**
 * The mailbox pool for a hosting account: the plan's total mailbox budget, how many
 * are used across ALL domains, each domain that currently hosts mail (with its
 * mailboxes + DNS state), and every account domain with attach-availability. Owner
 * or admin. This is the read side of the flexible-pool model and supersedes the
 * single-domain getHostingEmailStatus for the restructured Email surface.
 */
export async function getHostingEmailPool(accountId: string): Promise<HostingEmailPool> {
  const user = await requireUser();

  const account = await loadAccount(accountId);
  if (!account) return { error: "Not found." };
  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };

  const domains = accountDomains(account);
  const hosts = domains.map((d) => d.host);

  // Every non-cancelled subscription touching any account domain — for both the
  // global-dedup availability flags AND locating this account's bundled subs. Also
  // adopt any legacy unlinked bundled sub on the primary domain (back-compat).
  const subs = hosts.length
    ? await db.emailSubscription.findMany({
        where: { domainName: { in: hosts }, status: { not: "CANCELLED" } },
        include: { emailPlan: true, mailboxes: true },
      })
    : [];

  for (const s of subs) {
    if (
      s.hostingAccountId == null &&
      s.userId === account.userId &&
      s.domainName === normalizeDomain(account.primaryDomain) &&
      s.emailPlan.priceCents === 0 &&
      s.emailPlan.active === false
    ) {
      await db.emailSubscription.update({ where: { id: s.id }, data: { hostingAccountId: account.id } }).catch(() => {});
      s.hostingAccountId = account.id;
    }
  }

  const bundledSubs = subs.filter((s) => s.hostingAccountId === account.id);
  const bundledHosts = new Set(bundledSubs.map((s) => s.domainName));
  const poolUsed = bundledSubs.reduce((n, s) => n + s.mailboxes.length, 0);

  const domainOptions: HostingMailDomainOption[] = domains.map((d) => {
    const here = subs.filter((s) => s.domainName === d.host);
    return {
      host: d.host,
      kind: d.kind,
      free: isFreeSubdomain(d.host),
      hasEmail: here.length > 0,
      takenByOther: here.some((s) => s.userId !== account.userId),
      isCurrent: bundledHosts.has(d.host),
    };
  });

  const order = new Map(domains.map((d, i) => [d.host, i]));
  const mailDomains = bundledSubs
    .map((s) => toBundledView(account, s))
    .sort((a, b) => (order.get(a.domainName) ?? 99) - (order.get(b.domainName) ?? 99));

  return {
    planName: account.plan.name,
    poolCap: account.plan.mailboxes,
    poolUsed,
    primaryDomain: normalizeDomain(account.primaryDomain),
    domainOptions,
    mailDomains,
  };
}

/**
 * Find-or-create the bundled subscription that hosts mail on one of the account's
 * domains. Unlike setupHostingEmail (single bundled sub per account), the pool
 * permits one bundled sub PER domain — the cap is enforced on mailbox COUNT, not on
 * how many domains carry mail. Owner or admin; blocked while impersonating.
 */
export async function ensureHostingMailDomain(
  accountId: string,
  domainName: string,
): Promise<HostingPoolMailboxResult> {
  await requireUser();
  await assertNotImpersonating();

  const owned = await ownedAccount(accountId);
  if ("error" in owned) return { error: owned.error };
  const { account } = owned;

  const target = normalizeDomain(domainName);

  // Already hosting mail here for this account → reuse it (idempotent).
  const existing = await db.emailSubscription.findFirst({
    where: { hostingAccountId: account.id, domainName: target, status: { not: "CANCELLED" } },
  });
  if (existing) return { ok: true, subscriptionId: existing.id };

  const resolved = await resolveTargetDomain(account, domainName);
  if ("error" in resolved) return { error: resolved.error };
  const { domain, free } = resolved;

  const plan = await findBundledPlan(account.plan.mailboxes);
  if (!plan) {
    return {
      error:
        "Bundled email isn't configured for this plan yet. Please contact support — no charge, we'll switch it on.",
    };
  }

  const sub = await db.emailSubscription.create({
    data: {
      userId: account.userId,
      hostingAccountId: account.id,
      domainName: domain,
      emailPlanId: plan.id,
      status: "ACTIVE",
      autoRenew: true,
      expiresAt: account.expiresAt,
      external: !free,
      verified: free,
      verifiedAt: free ? new Date() : null,
      verifyToken: free ? null : randomBytes(24).toString("hex"),
    },
  });

  await db.auditLog
    .create({
      data: {
        userId: account.userId,
        action: "hostingemail.pooldomain",
        detail: `${domain} · bundled ${plan.name} via hosting ${account.plan.name} (pool)`,
      },
    })
    .catch(() => {});

  if (free) await autoConfigureFreeSubdomain(account.userId, domain);

  revalidatePath(`/dashboard/hosting/${accountId}`);
  revalidatePath("/dashboard/email");
  return { ok: true, subscriptionId: sub.id };
}

/**
 * Add one mailbox to the pool, on the chosen domain. Enforces the plan's mailbox
 * budget across EVERY domain the account hosts mail on (this is what makes the pool
 * flexible yet capped), ensures the domain's bundled subscription exists, then
 * delegates the real creation to the audited addMailbox (address validation, verify
 * gate for external domains, Mailcow provisioning). Owner-only via addMailbox.
 */
export async function addHostingPoolMailbox(
  accountId: string,
  domainName: string,
  localPart: string,
): Promise<HostingPoolMailboxResult> {
  const user = await requireUser();
  await assertNotImpersonating();

  const owned = await ownedAccount(accountId);
  if ("error" in owned) return { error: owned.error };
  const { account } = owned;

  // Pool cap: total mailboxes across ALL of this account's bundled subscriptions.
  const bundledSubs = await db.emailSubscription.findMany({
    where: { hostingAccountId: account.id, status: { not: "CANCELLED" } },
    include: { mailboxes: { select: { id: true } } },
  });
  const used = bundledSubs.reduce((n, s) => n + s.mailboxes.length, 0);
  if (used >= account.plan.mailboxes) {
    return {
      error: `Mailbox pool full (${used} of ${account.plan.mailboxes} used). Remove one, or upgrade your plan for more.`,
    };
  }

  const ensured = await ensureHostingMailDomain(accountId, domainName);
  if (ensured.error || !ensured.subscriptionId) return { error: ensured.error ?? "Couldn't attach the domain." };

  // Ownership belt-and-braces: addMailbox is owner-only, and we required the user
  // above; guard the delegation so an admin path fails cleanly rather than oddly.
  if (account.userId !== user.id) {
    return { error: "Mailboxes can only be added by the account owner." };
  }

  const r = await addMailbox(ensured.subscriptionId, localPart);
  if (r.error) return { error: r.error };
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true, subscriptionId: ensured.subscriptionId };
}

