"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import Link from "next/link";
import {
  getHostingEmailPool,
  ensureHostingMailDomain,
  addHostingPoolMailbox,
  type HostingEmailPool,
  type HostingMailDomainOption,
  type HostingBundledEmail,
  type HostingMailbox,
} from "@/lib/hosting-email";
import {
  removeMailbox,
  revealMailboxPassword,
  resetMailboxPassword,
  retryMailboxProvision,
  checkEmailDeliverability,
} from "@/lib/actions-email-hosting";
import type { DeliverabilityReport, CheckStatus } from "@/lib/mail/deliverability";
import type { HostingAccountView } from "@/lib/actions-hosting";
import { EmailDnsSetup } from "@/components/customer/EmailDnsSetup";
import { Badge } from "@/components/ui/primitives";
import { Icon } from "@/components/ui/Icon";

/**
 * THE FLEXIBLE MAILBOX POOL — the headline email surface.
 *
 * The plan unlocks N mailboxes and the customer spreads them across ANY of their
 * domains (5 on shop.com, 3 on blog.com) — never all pinned to one. This component
 * shows pool usage (X of N used across all domains), each domain that hosts mail
 * with its mailboxes + DNS, and an "add a mailbox → pick its domain" flow. Every
 * add is enforced against the shared pool via addHostingPoolMailbox.
 *
 * Two entry points, one model:
 *   • <EmailPool account />                     — plan-level: all domains.
 *   • <EmailPool account siteDomain=".." />     — website-scoped: just this site's
 *     domain (a filtered view of the same pool), for the Website page Email tab.
 */
export function EmailTab({ account, siteDomain }: { account: HostingAccountView; siteDomain?: string }) {
  const [pool, setPool] = useState<HostingEmailPool | null>(null);
  const [err, setErr] = useState<string | null>(null);

  const refresh = useCallback(() => {
    getHostingEmailPool(account.id)
      .then((p) => setPool(p))
      .catch(() => setPool({ error: "Couldn't load email." }));
  }, [account.id]);

  useEffect(() => { refresh(); }, [refresh]);

  if (!pool) {
    return <div className="card py-12 text-center text-sm text-slate-400">Loading email…</div>;
  }
  if (pool.error) {
    return <div className="card py-12 text-center text-sm text-red-300">{pool.error}</div>;
  }

  const cap = pool.poolCap ?? 0;
  const used = pool.poolUsed ?? 0;
  const mailboxWord = cap === 1 ? "mailbox" : "mailboxes";
  const options = pool.domainOptions ?? [];
  const scoped = siteDomain ? siteDomain.toLowerCase() : null;

  if (cap <= 0) {
    return (
      <div className="card">
        <h2 className="mb-2 font-semibold">Email</h2>
        <p className="text-sm text-slate-400">
          Your <span className="text-white">{pool.planName}</span> plan doesn&apos;t include any mailboxes.
          Upgrade your plan to add professional you@yourdomain email.
        </p>
      </div>
    );
  }

  // ---- Website-scoped variant: only this site's domain --------------------
  if (scoped) {
    const opt = options.find((o) => o.host === scoped);
    const domain = pool.mailDomains?.find((d) => d.domainName === scoped) ?? null;
    return (
      <div className="space-y-5">
        <PoolMeter used={used} cap={cap} planName={pool.planName} scopedNote={`Mailboxes on ${scoped} draw from your shared pool.`} />
        {err && <div className="card border-red-500/30 text-sm text-red-300">{err}</div>}
        {opt?.takenByOther ? (
          <div className="card border-amber-500/30 text-sm text-amber-300">
            <span className="font-mono">{scoped}</span> is already set up for email on another account.
          </div>
        ) : domain ? (
          <MailDomainCard
            accountId={account.id}
            domain={domain}
            poolFull={used >= cap}
            onChanged={() => { setErr(null); refresh(); }}
            onError={setErr}
          />
        ) : (
          <SetupOnDomain
            accountId={account.id}
            host={scoped}
            free={opt?.free ?? false}
            poolFull={used >= cap}
            onDone={() => { setErr(null); refresh(); }}
            onError={setErr}
          />
        )}
        <p className="text-xs text-slate-500">
          Manage the whole pool in the plan{" "}
          <span className="text-slate-300">Email</span> section, or the full{" "}
          <Link href="/dashboard/email" className="text-brand-300 hover:underline">email dashboard</Link>.
        </p>
      </div>
    );
  }

  // ---- Plan-level: the full pool across every domain ----------------------
  const usableToAdd = options.filter((o) => !o.takenByOther);
  return (
    <div className="space-y-6">
      <PoolMeter used={used} cap={cap} planName={pool.planName} />
      <p className="text-sm text-slate-300">
        Your <span className="font-medium text-white">{pool.planName}</span> plan includes{" "}
        <span className="font-medium text-white">{cap} {mailboxWord}</span> — spread them across any of
        your domains. Professional you@yourdomain email at no extra cost.
      </p>

      {err && <div className="card border-red-500/30 text-sm text-red-300">{err}</div>}

      {(pool.mailDomains ?? []).map((d) => (
        <MailDomainCard
          key={d.subscriptionId}
          accountId={account.id}
          domain={d}
          poolFull={used >= cap}
          onChanged={() => { setErr(null); refresh(); }}
          onError={setErr}
        />
      ))}

      <AddOnNewDomain
        accountId={account.id}
        options={usableToAdd}
        existing={new Set((pool.mailDomains ?? []).map((d) => d.domainName))}
        poolFull={used >= cap}
        onDone={() => { setErr(null); refresh(); }}
        onError={setErr}
      />

      <p className="text-xs text-slate-500">
        These mailboxes are also fully manageable from the{" "}
        <Link href="/dashboard/email" className="text-brand-300 hover:underline">email dashboard</Link>.
      </p>
    </div>
  );
}

/* -------------------------------------------------------------- Pool meter --- */

function PoolMeter({ used, cap, planName, scopedNote }: { used: number; cap: number; planName?: string; scopedNote?: string }) {
  const pct = cap > 0 ? Math.min(100, Math.round((used / cap) * 100)) : 0;
  const full = used >= cap;
  return (
    <div className="card">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h2 className="flex items-center gap-2 font-semibold">
          <Icon name="mail" size={17} className="text-brand-300" /> Mailbox pool
        </h2>
        <span className={`text-sm font-semibold ${full ? "text-amber-300" : "text-slate-200"}`}>
          {used} <span className="font-normal text-slate-500">of</span> {cap} used
        </span>
      </div>
      <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-white/[0.06]">
        <div
          className={`h-full rounded-full ${full ? "bg-amber-400" : "bg-gradient-to-r from-accent-blue to-brand-500"}`}
          style={{ width: `${pct}%` }}
        />
      </div>
      <p className="mt-2 text-xs text-slate-500">
        {scopedNote ?? "Allocate these mailboxes across any of your domains — the count is shared, not pinned to one."}
      </p>
    </div>
  );
}

/* -------------------------------------------------------------- Domain card --- */

function kindLabel(kind: string): string {
  return kind === "primary" ? "Primary" : kind === "subdomain" ? "Subdomain" : "Custom domain";
}

function MailDomainCard({
  accountId,
  domain,
  poolFull,
  onChanged,
  onError,
}: {
  accountId: string;
  domain: HostingBundledEmail;
  poolFull: boolean;
  onChanged: () => void;
  onError: (e: string) => void;
}) {
  return (
    <div className="card">
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="font-mono text-sm text-white">{domain.domainName}</span>
          <Badge tone="slate">{kindLabel(domain.kind)}</Badge>
          {domain.free ? (
            <Badge tone="green">Auto DNS</Badge>
          ) : domain.verified ? (
            <Badge tone="green">Verified</Badge>
          ) : (
            <Badge tone="amber">Verify DNS</Badge>
          )}
        </div>
        <span className="text-xs text-slate-500">{domain.mailboxes.length} on this domain</span>
      </div>

      {/* Per-domain DNS: free → we own the zone; real → registrar records + verify. */}
      {domain.free ? (
        <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-slate-400">
          Free Nxeon subdomain — its mail DNS (MX, SPF, DKIM, DMARC) is published in the zone we control.
          Run the deliverability check to confirm every record is live.
        </div>
      ) : (
        <EmailDnsSetup subscriptionId={domain.subscriptionId} domainName={domain.domainName} verified={domain.verified} />
      )}

      <div className="mt-3">
        <DeliverabilityCheck subscriptionId={domain.subscriptionId} domainName={domain.domainName} />
      </div>

      <div className="mt-4">
        {domain.mailboxes.length === 0 ? (
          <p className="text-sm text-slate-500">No mailboxes on this domain yet.</p>
        ) : (
          <div className="space-y-2">
            {domain.mailboxes.map((m) => (
