/* ---- website-scoped: set up email on this site's domain the first time ------ */

function SetupOnDomain({
  accountId,
  host,
  free,
  poolFull,
  onDone,
  onError,
}: {
  accountId: string;
  host: string;
  free: boolean;
  poolFull: boolean;
  onDone: () => void;
  onError: (e: string) => void;
}) {
  const [local, setLocal] = useState("");
  const [pending, start] = useTransition();

  function submit() {
    const v = local.trim();
    if (!v) { onError("Enter a mailbox name."); return; }
    start(async () => {
      const r = await addHostingPoolMailbox(accountId, host, v);
      if (r.error) onError(r.error);
      else { setLocal(""); onDone(); }
    });
  }

  return (
    <div className="card">
      <h3 className="mb-1 font-semibold">Add email on this website</h3>
      <p className="mb-3 text-sm text-slate-400">
        Create your first mailbox on <span className="font-mono text-slate-200">{host}</span>. It draws
        from your plan&apos;s shared mailbox pool.{" "}
        {free
          ? "As a free Nxeon subdomain, its mail DNS is configured automatically."
          : "You'll publish MX/SPF/DKIM at your registrar, then verify."}
      </p>
      {poolFull ? (
        <p className="text-sm text-amber-400">Your mailbox pool is full — remove one elsewhere or upgrade your plan.</p>
      ) : (
        <div className="flex flex-wrap items-end gap-2">
          <div className="min-w-0 flex-1">
            <label className="label">New mailbox</label>
            <div className="flex items-center">
              <input
                className="input rounded-r-none"
                value={local}
                placeholder="hello"
                onChange={(e) => setLocal(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
              />
              <span className="rounded-r-lg border border-l-0 border-white/10 bg-white/[0.03] px-3 py-2 text-sm text-slate-400">
                @{host}
              </span>
            </div>
          </div>
          <button className="btn-primary" disabled={pending} onClick={submit}>
            {pending ? "Adding…" : "Add mailbox"}
          </button>
        </div>
      )}
    </div>
  );
}

/* ---- plan-level: add a mailbox on a domain that has no mail yet ------------- */

function AddOnNewDomain({
  accountId,
  options,
  existing,
  poolFull,
  onDone,
  onError,
}: {
  accountId: string;
  options: HostingMailDomainOption[];
  existing: Set<string>;
  poolFull: boolean;
  onDone: () => void;
  onError: (e: string) => void;
}) {
  const fresh = options.filter((o) => !existing.has(o.host) && !o.hasEmail);
  const [open, setOpen] = useState(false);
  const [chosen, setChosen] = useState(fresh[0]?.host ?? "");
  const [local, setLocal] = useState("");
  const [pending, start] = useTransition();

  if (fresh.length === 0) {
    return (
      <div className="card border-dashed text-sm text-slate-500">
        Every domain on this plan already hosts mail (or is unavailable). Add a domain in the{" "}
        <span className="text-slate-300">Domains</span> section to spread the pool further.
      </div>
    );
  }

  if (!open) {
    return (
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-white/15 py-4 text-sm font-medium text-slate-300 transition-colors hover:border-brand-400 hover:text-white"
      >
        <Icon name="plus" size={16} /> Add a mailbox on another domain
      </button>
    );
  }

  function submit() {
    const v = local.trim();
    if (!chosen) { onError("Pick a domain."); return; }
    if (!v) { onError("Enter a mailbox name."); return; }
    start(async () => {
      const r = await addHostingPoolMailbox(accountId, chosen, v);
      if (r.error) onError(r.error);
      else { setLocal(""); setOpen(false); onDone(); }
    });
  }

  const chosenOpt = fresh.find((o) => o.host === chosen);
  return (
    <div className="card">
      <div className="mb-3 flex items-center justify-between">
        <h3 className="font-semibold">Add a mailbox on another domain</h3>
        <button type="button" className="btn-ghost text-xs text-slate-400 hover:text-white" onClick={() => setOpen(false)}>Cancel</button>
      </div>
      {poolFull ? (
        <p className="text-sm text-amber-400">Your mailbox pool is full — remove one or upgrade your plan.</p>
      ) : (
        <>
          <label className="label">Domain</label>
          <select className="input" value={chosen} onChange={(e) => setChosen(e.target.value)}>
            {fresh.map((o) => (
              <option key={o.host} value={o.host}>
                {o.host} — {kindLabel(o.kind)}{o.free ? " (auto DNS)" : ""}
              </option>
            ))}
          </select>
          <label className="label mt-3">New mailbox</label>
          <div className="flex items-center">
            <input
              className="input rounded-r-none"
              value={local}
              placeholder="hello"
              onChange={(e) => setLocal(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
            />
            <span className="rounded-r-lg border border-l-0 border-white/10 bg-white/[0.03] px-3 py-2 text-sm text-slate-400">
              @{chosen}
            </span>
          </div>
          {chosenOpt && !chosenOpt.free && (
            <p className="mt-2 text-xs text-slate-500">
              You&apos;ll publish MX/SPF/DKIM for <span className="font-mono">{chosen}</span> and verify it before mail flows.
            </p>
          )}
          <button className="btn-primary mt-4" disabled={pending} onClick={submit}>
            {pending ? "Adding…" : "Add mailbox"}
          </button>
        </>
      )}
    </div>
  );
}

