/* --------------------------------------------------------------- Mailboxes --- */

function statusBadge(status: string): { tone: "green" | "amber" | "red" | "slate"; label: string } {
  switch (status) {
    case "ACTIVE": return { tone: "green", label: "Active" };
    case "FAILED": return { tone: "red", label: "Setup failed" };
    case "SUSPENDED": return { tone: "slate", label: "Suspended" };
    case "PROVISIONING": return { tone: "amber", label: "Provisioning" };
    default: return { tone: "slate", label: status || "Unknown" };
  }
}

function MailboxRow({
  mailbox,
  onChanged,
  onError,
}: {
  mailbox: HostingMailbox;
  onChanged: () => void;
  onError: (e: string) => void;
}) {
  const [pending, start] = useTransition();
  const [pwPending, startPw] = useTransition();
  const [password, setPassword] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const badge = statusBadge(mailbox.status);
  const usable = mailbox.status === "ACTIVE";
  const retryable = mailbox.status === "FAILED" || mailbox.status === "PROVISIONING";

  function retry() {
    startPw(async () => {
      const res = await retryMailboxProvision(mailbox.id);
      if (res?.error) onError(res.error);
      else onChanged();
    });
  }
  function reveal() {
    setNote(null);
    startPw(async () => {
      const res = await revealMailboxPassword(mailbox.id);
      if (res?.error) onError(res.error);
      else if (res?.password) { setPassword(res.password); setNote("Sign in with your full address."); }
    });
  }
  function resetPw() {
    if (!confirm(`Reset the password for ${mailbox.address}? The current one stops working.`)) return;
    setNote(null);
    startPw(async () => {
      const res = await resetMailboxPassword(mailbox.id);
      if (res?.error) onError(res.error);
      else if (res?.password) { setPassword(res.password); setNote("New password — copy it now."); }
    });
  }
  function remove() {
    if (!confirm(`Remove mailbox ${mailbox.address}?`)) return;
    start(async () => {
      const res = await removeMailbox(mailbox.id);
      if (res?.error) onError(res.error);
      else onChanged();
    });
  }

  return (
    <div className="rounded-lg border border-white/[0.06] px-3 py-2">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="font-mono text-sm text-white">{mailbox.address}</span>
          <Badge tone={badge.tone}>{badge.label}</Badge>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {usable && (
            <Link href={`/dashboard/mail?mailbox=${encodeURIComponent(mailbox.address)}`} className="btn-secondary py-1 text-xs">
              Open inbox →
            </Link>
          )}
          {retryable && (
            <button className="btn-secondary py-1 text-xs" disabled={pwPending} onClick={retry}>
              {pwPending ? "…" : "Retry setup"}
            </button>
          )}
          <button className="btn-secondary py-1 text-xs" disabled={pwPending} onClick={reveal}>
            {password ? "Refresh password" : "Show password"}
          </button>
          <button className="btn-secondary py-1 text-xs" disabled={pwPending} onClick={resetPw}>
            Reset password
          </button>
          <button className="btn-danger py-1 text-xs" disabled={pending} onClick={remove}>
            Remove
          </button>
        </div>
      </div>
      {mailbox.status === "FAILED" && (
        <p className="mt-2 text-xs text-red-400">
          Not created on the mail server — mail to it is rejected. Press Retry setup.
        </p>
      )}
      {password && (
        <div className="mt-2 flex items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
          <code className="min-w-0 flex-1 truncate rounded bg-white/[0.04] px-2 py-1 font-mono text-xs text-slate-100">
            {password}
          </code>
          <button type="button" className="btn-secondary shrink-0 px-2 py-1 text-xs" onClick={() => navigator.clipboard?.writeText(password).catch(() => {})}>
            Copy
          </button>
          <button type="button" className="btn-secondary shrink-0 px-2 py-1 text-xs" onClick={() => { setPassword(null); setNote(null); }}>
            Hide
          </button>
        </div>
      )}
      {note && <p className="mt-1 text-[11px] text-slate-500">{note}</p>}
    </div>
  );
}

/* ---------------------------------------------------------- Deliverability --- */

const CHECK_TONE: Record<CheckStatus, "green" | "amber" | "red" | "slate"> = {
  pass: "green", warn: "amber", fail: "red", unknown: "slate",
};
const CHECK_LABEL: Record<CheckStatus, string> = {
  pass: "Pass", warn: "Warning", fail: "Fail", unknown: "Unknown",
};

function DeliverabilityCheck({ subscriptionId, domainName }: { subscriptionId: string; domainName: string }) {
  const [report, setReport] = useState<DeliverabilityReport | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function run() {
    setError(null);
    start(async () => {
      const res = await checkEmailDeliverability(subscriptionId);
      if (res?.error) { setError(res.error); setReport(null); }
      else if (res?.report) setReport(res.report);
    });
  }

  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;

  return (
    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-sm font-semibold text-white">Deliverability check</span>
          {report &&
            (failing > 0 ? (
              <Badge tone="red">{failing} problem{failing === 1 ? "" : "s"}</Badge>
            ) : unknown > 0 ? (
              <Badge tone="slate">Incomplete</Badge>
            ) : warning > 0 ? (
              <Badge tone="amber">{warning} warning{warning === 1 ? "" : "s"}</Badge>
            ) : (
              <Badge tone="green">All checks pass</Badge>
            ))}
        </div>
        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
        </button>
      </div>
      <p className="mt-2 text-xs text-slate-400">
        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
        and DMARC. A failing row here is usually why mail lands in spam.
      </p>
      {error && (
        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">{error}</div>
      )}
      {report && (
        <div className="mt-3 space-y-2">
          {report.error && (
            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">{report.error}</div>
          )}
          {report.checks.map((c) => (
            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
              <div className="flex flex-wrap items-center gap-2">
                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
                <span className="text-sm font-medium text-slate-200">{c.label}</span>
                <span className="text-[11px] text-slate-500">{c.type} · <span className="font-mono">{c.host}</span></span>
              </div>
              <div className="mt-2 grid gap-2 sm:grid-cols-2">
                <div className="min-w-0">
                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
                    {c.observed || "— nothing published —"}
                  </code>
                </div>
                <div className="min-w-0">
                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
                    {c.expected || "—"}
                  </code>
                </div>
              </div>
              <p className={`mt-2 text-xs ${c.status === "fail" ? "text-red-400" : c.status === "warn" ? "text-amber-400" : c.status === "pass" ? "text-emerald-300/80" : "text-slate-400"}`}>
                {c.detail}
              </p>
            </div>
          ))}
          <p className="text-[11px] text-slate-500">
            {report.nameservers.length > 0 ? (
              <>Read directly from this domain&apos;s nameservers (<span className="font-mono">{report.nameservers.join(", ")}</span>).</>
            ) : (
              <>Couldn&apos;t reach this domain&apos;s nameservers, so no record could be read.</>
            )}{" "}
            Checked {new Date(report.checkedAt).toLocaleTimeString()}.
          </p>
        </div>
      )}
    </div>
  );
}

