/* --------------------------------------------------------- website cards --- */

function targetOf(w: HostingWebsiteView): SiteTarget {
  if (w.kind === "subdomain" && w.id) return { kind: "subdomain", id: w.id };
  if (w.kind === "addon" && w.id) return { kind: "addon", id: w.id };
  return { kind: "primary" };
}

/** A short, non-primary-centric type label. */
function kindLabel(w: HostingWebsiteView): string {
  if (w.isFreeSubdomain) return "Free subdomain";
  if (w.kind === "subdomain") return "Subdomain";
  if (w.kind === "addon") return "Custom domain";
  return "Website"; // the primary site reads as a plain website, not "Primary"
}

function WebsiteCard({
  site, accountId, onManage, onOpenSite, onSitesChanged,
}: {
  site: HostingWebsiteView; accountId: string; onManage: () => void;
  onOpenSite: (p: string) => void; onSitesChanged: () => void;
}) {
  const [menu, setMenu] = useState(false);
  const [busy, setBusy] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const settling = site.status === "PENDING" || site.status === "DELETING";

  useEffect(() => {
    function onDoc(e: MouseEvent) { if (ref.current && !ref.current.contains(e.target as Node)) setMenu(false); }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  async function promote() {
    if (!site.id) return;
    setMenu(false);
    if (!confirm(`Make ${site.hostname} the main address for this plan? The old address keeps working as an alias.`)) return;
    setBusy(true);
    const r = await setPrimaryHostingDomain(accountId, site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }
  async function remove() {
    if (!site.id) return;
    setMenu(false);
    if (!confirm(`Delete ${site.hostname}? Its files will be removed.`)) return;
    setBusy(true);
    const r = site.kind === "subdomain" ? await deleteSubdomain(site.id) : await deleteAddonDomain(site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }

  return (
    <div className="card card-hover overflow-hidden p-0">
      <button type="button" onClick={onManage} disabled={settling} className="block w-full text-left" aria-label={`Open ${site.hostname}`}>
        <div className="relative aspect-[16/9] w-full border-b border-white/[0.06]">
          <Thumbnail accountId={accountId} site={site} />
          <div className="absolute left-2.5 top-2.5 flex flex-wrap gap-1.5">
            {site.status === "ACTIVE"
              ? <Badge tone="green">Live</Badge>
              : <span className="rounded-full bg-navy-900/80 px-1.5 py-0.5 backdrop-blur"><StatusDot status={site.status} /></span>}
          </div>
        </div>
      </button>

      <div className="flex gap-3 p-4">
        <AppBadge installedApp={site.installedApp} size={40} />
        <div className="min-w-0 flex-1">
          <a
            href={site.sslActive ? `https://${site.hostname}` : `http://${site.hostname}`}
            target="_blank"
            rel="noreferrer"
            className="block truncate font-mono text-sm font-medium text-slate-100 hover:underline"
            title={site.hostname}
          >
            {site.hostname}
          </a>
          <div className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-slate-400">
            <span>{site.installedApp ?? "No app"}</span>
            <span className="text-slate-600">·</span>
            <span>{kindLabel(site)}</span>
          </div>
        </div>
      </div>

      <div className="flex flex-wrap gap-x-4 gap-y-1 px-4 pb-3 text-[11px] text-slate-500">
        <span className="inline-flex items-center gap-1">
          <Icon name={site.sslActive ? "lock" : "shield"} size={12} /> {site.sslActive ? "HTTPS" : "HTTP"}
        </span>
        <span>PHP {site.phpVersion}</span>
        <span className="truncate font-mono">{site.fileManagerPath}</span>
      </div>

      <div className="relative flex gap-2 border-t border-white/[0.06] bg-white/[0.02] p-3" ref={ref}>
        <button className="btn-primary flex-1 py-1.5 text-xs" disabled={busy || settling} onClick={onManage}>{busy ? "Working…" : "Manage"}</button>
        <button className="btn-secondary inline-flex items-center px-3 py-1.5 text-xs" disabled={busy || settling} onClick={() => setMenu((m) => !m)} aria-label="More actions">
          <Icon name="more-horizontal" size={16} />
        </button>
        {menu && (
          <div className="absolute bottom-full right-3 z-20 mb-1 w-52 overflow-hidden rounded-xl border border-white/[0.08] bg-navy-900/95 p-1 shadow-xl backdrop-blur-md">
            <MenuItem icon="grid" onClick={() => { setMenu(false); onManage(); }}>Open website</MenuItem>
            <MenuItem icon="folder" onClick={() => { setMenu(false); onOpenSite(site.id ?? "primary"); }}>Manage files</MenuItem>
            <a href={site.sslActive ? `https://${site.hostname}` : `http://${site.hostname}`} target="_blank" rel="noreferrer" className="flex items-center gap-2 rounded-lg px-3 py-2 text-sm text-slate-200 hover:bg-white/[0.05]">
              <Icon name="external-link" size={15} /> Visit site
            </a>
            {site.canSetPrimary && <MenuItem icon="star" onClick={promote}>Set as main address</MenuItem>}
            {(site.kind === "subdomain" || site.kind === "addon") && (
              <button type="button" onClick={remove} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm text-red-300 hover:bg-red-500/10">
                <Icon name="trash" size={15} /> Delete website
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function MenuItem({ children, icon, onClick }: { children: ReactNode; icon: IconName; onClick: () => void }) {
  return (
    <button type="button" onClick={onClick} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm text-slate-200 hover:bg-white/[0.05]">
      <Icon name={icon} size={15} /> {children}
    </button>
  );
}

/* ==================================================== add-website wizard ==== */

type WizStep = "name" | "domain" | "app" | "live";
type DomainMode = "free" | "connect" | "buy";

function AddWebsiteWizard({
  account, onClose, onCreated,
}: {
  account: HostingAccountView;
  onClose: () => void;
  onCreated: (openParam?: string) => void;
}) {
  const [step, setStep] = useState<WizStep>("name");
  const [name, setName] = useState("");
  const [mode, setMode] = useState<DomainMode>("free");

  // free subdomain
  const [label, setLabel] = useState("");
  const [check, setCheck] = useState<{ available: boolean; fqdn: string; reason?: string } | null>(null);
  // connect existing
  const [domain, setDomain] = useState("");
  // app
  const [appChoice, setAppChoice] = useState<"wordpress" | "blank" | "other">("wordpress");
  const [otherApp, setOtherApp] = useState("");
  const [apps, setApps] = useState<{ slug: string; name: string; needsDb: boolean }[]>([]);

  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [liveHost, setLiveHost] = useState<string | null>(null);
  const [liveParam, setLiveParam] = useState<string | undefined>(undefined);

  useEffect(() => { listAppCatalog().then(setApps).catch(() => {}); }, []);

  // Suggest a subdomain slug from the friendly name until the user edits the slug.
  const slugTouched = useRef(false);
  useEffect(() => {
    if (slugTouched.current) return;
    const slug = name.trim().toLowerCase().replace(/[^a-z0-9-]/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "").slice(0, 32);
    setLabel(slug);
  }, [name]);

  useEffect(() => {
    if (mode !== "free") return;
    const l = label.trim().toLowerCase();
    if (!l) { setCheck(null); return; }
    let live = true;
    const t = setTimeout(() => { checkHostingSubdomain(l).then((r) => { if (live) setCheck(r); }).catch(() => {}); }, 350);
    return () => { live = false; clearTimeout(t); };
  }, [label, mode]);

  const freeOk = check?.available === true;
  const canCreate = mode === "free" ? freeOk : mode === "connect" ? domain.trim().length > 3 : false;

  async function create() {
    setBusy(true); setErr("");
    const res = mode === "free"
      ? await createFreeSubdomainSite(account.id, label.trim().toLowerCase())
      : await createAddonDomain(account.id, domain.trim());
    if (res.error) { setBusy(false); setErr(res.error); return; }

    const host = mode === "free" ? `${label.trim().toLowerCase()}.${account.subdomainBase}` : domain.trim().toLowerCase();
    setLiveHost(host);

    // Find the freshly-created website so we can (a) deep-link to it and (b) install
    // the chosen app onto its docroot.
    let created: HostingWebsiteView | undefined;
    try {
      const list = await listWebsites(account.id);
      created = list.find((w) => w.hostname.toLowerCase() === host);
    } catch { /* */ }
    if (created) setLiveParam(created.id ?? "primary");

    if (created && appChoice !== "blank") {
      const t = targetOf(created);
      const r = appChoice === "wordpress" ? await installWordPress(account.id, t) : await installApp(account.id, otherApp, t);
      if (r.error) setErr(`Website created, but the app install couldn't start: ${r.error}`);
    }

    setBusy(false);
    setStep("live");
  }

  const steps: WizStep[] = ["name", "domain", "app", "live"];
  const idx = steps.indexOf(step);

  return (
    <div className="fixed inset-0 z-40 flex items-start justify-center overflow-y-auto bg-navy-900/70 p-4 backdrop-blur-sm" onMouseDown={onClose}>
      <div className="card mt-12 w-full max-w-lg p-0" onMouseDown={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between border-b border-white/[0.06] px-5 py-4">
          <h3 className="font-semibold">Add a website</h3>
          <button type="button" onClick={onClose} className="btn-ghost inline-flex h-8 w-8 items-center justify-center p-0 text-slate-400 hover:text-white" aria-label="Close">
            <Icon name="plus" size={18} className="rotate-45" />
          </button>
        </div>

        {/* step rail */}
        {step !== "live" && (
          <div className="flex items-center gap-2 px-5 pt-4 text-[11px] text-slate-500">
            {["Name", "Domain", "What is it"].map((s, i) => (
              <div key={s} className="flex items-center gap-2">
                <span className={`flex h-5 w-5 items-center justify-center rounded-full border text-[10px] ${i <= idx ? "border-brand-400/50 bg-brand-500/15 text-brand-200" : "border-white/10 text-slate-500"}`}>{i + 1}</span>
                <span className={i === idx ? "text-slate-200" : ""}>{s}</span>
                {i < 2 && <span className="text-slate-700">›</span>}
              </div>
            ))}
          </div>
        )}

        <div className="px-5 py-5">
          {step === "name" && (
            <div>
              <label className="label">Name your website</label>
              <input
                className="input mt-1 w-full"
                placeholder="My Store"
                value={name}
                autoFocus
                maxLength={60}
                onChange={(e) => setName(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter" && name.trim()) setStep("domain"); }}
              />
              <p className="mt-2 text-xs text-slate-500">A friendly label to recognise it by. We&apos;ll suggest a matching address next — you can change it.</p>
              <div className="mt-5 flex justify-end">
                <button className="btn-primary text-sm" disabled={!name.trim()} onClick={() => setStep("domain")}>Continue</button>
              </div>
            </div>
          )}

          {step === "domain" && (
            <div>
              <label className="label">Choose a domain</label>
              <div className="mb-4 mt-1 flex gap-1 rounded-xl border border-white/[0.06] bg-white/[0.02] p-1">
                {([["free", "Free subdomain"], ["connect", "Connect yours"], ["buy", "Buy one"]] as [DomainMode, string][]).map(([m, lbl]) => (
                  <button key={m} type="button" onClick={() => setMode(m)} className={`flex-1 rounded-lg px-2 py-1.5 text-xs font-medium transition-colors ${mode === m ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white" : "text-slate-400 hover:text-white"}`}>
                    {lbl}
                  </button>
                ))}
              </div>

              {mode === "free" && (
                <div>
                  <div className="flex items-stretch overflow-hidden rounded-lg border border-white/[0.1] bg-white/[0.03] focus-within:border-brand-400">
                    <input
                      className="min-w-0 flex-1 bg-transparent px-3 py-2 text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none"
                      placeholder="myshop"
                      value={label}
                      maxLength={32}
                      autoFocus
                      onChange={(e) => { slugTouched.current = true; setLabel(e.target.value.replace(/[^a-zA-Z0-9-]/g, "")); }}
                    />
                    <span className="flex items-center whitespace-nowrap border-l border-white/[0.08] bg-white/[0.02] px-3 font-mono text-sm text-slate-400">.{account.subdomainBase}</span>
                  </div>
                  {label.trim() && check && (
                    <p className={`mt-2 flex items-center gap-1.5 text-xs ${freeOk ? "text-emerald-300" : "text-amber-300"}`}>
                      <Icon name={freeOk ? "check" : "clock"} size={13} />
                      {freeOk ? `${check.fqdn} is available` : check.reason ?? "Checking…"}
                    </p>
                  )}
                  <p className="mt-3 text-xs text-slate-500">Instant and free — it resolves and gets HTTPS automatically, nothing to point.</p>
                </div>
              )}

              {mode === "connect" && (
                <div>
                  <input
                    className="input w-full text-sm"
                    placeholder="example.com"
                    value={domain}
                    autoFocus
                    onChange={(e) => setDomain(e.target.value)}
                  />
                  <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5 text-xs text-slate-400">
                    Point it at us with an <span className="font-mono text-slate-200">A</span> record to{" "}
                    <span className="font-mono text-brand-200">{account.pointToA}</span>. HTTPS is issued automatically once it resolves.
                  </div>
                </div>
              )}

              {mode === "buy" && (
                <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-4 py-5 text-center">
                  <Icon name="search" size={22} className="mx-auto text-brand-300" />
                  <p className="mt-2 text-sm text-slate-300">Search and register a new domain, then come back and connect it to this website.</p>
                  <a href="/dashboard/domains/register" className="btn-primary mt-3 inline-flex items-center gap-1.5 text-sm">
                    <Icon name="external-link" size={14} /> Find a domain
                  </a>
                  <p className="mt-3 text-xs text-slate-500">Or connect a domain you already own with &quot;Connect yours&quot;.</p>
                </div>
              )}

              {err && <p className="mt-3 text-sm text-red-400">{err}</p>}
              <div className="mt-5 flex justify-between">
                <button className="btn-secondary text-sm" onClick={() => setStep("name")}>Back</button>
                {mode !== "buy" && (
                  <button className="btn-primary text-sm" disabled={!canCreate} onClick={() => setStep("app")}>Continue</button>
                )}
              </div>
            </div>
          )}

          {step === "app" && (
            <div>
              <label className="label">What is this website?</label>
              <div className="mt-1 space-y-2">
                <AppOption active={appChoice === "wordpress"} onClick={() => setAppChoice("wordpress")} logo="wordpress" title="WordPress" sub="Recommended — the world's most popular site builder, installed for you." />
                <AppOption active={appChoice === "blank"} onClick={() => setAppChoice("blank")} icon="file" title="Blank + upload files" sub="Start empty and upload your own site or static files." />
                <AppOption active={appChoice === "other"} onClick={() => setAppChoice("other")} icon="grid" title="Another app" sub="Ghost, Nextcloud, and more from the catalog." />
              </div>
              {appChoice === "other" && (
                <select className="input mt-3" value={otherApp} onChange={(e) => setOtherApp(e.target.value)}>
                  <option value="">Choose an app…</option>
                  {apps.map((a) => (<option key={a.slug} value={a.slug}>{a.name}</option>))}
                </select>
              )}
              {err && <p className="mt-3 text-sm text-red-400">{err}</p>}
              <div className="mt-5 flex justify-between">
                <button className="btn-secondary text-sm" onClick={() => setStep("domain")}>Back</button>
                <button className="btn-primary text-sm" disabled={busy || (appChoice === "other" && !otherApp)} onClick={create}>
                  {busy ? "Creating…" : "Create website"}
                </button>
              </div>
            </div>
          )}

          {step === "live" && (
            <div className="text-center">
              <div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl border border-emerald-500/30 bg-emerald-500/10 text-emerald-300">
                <Icon name="check" size={24} />
              </div>
              <h3 className="mt-3 text-lg font-semibold">Your website is live</h3>
              {liveHost && (
                <a href={`http://${liveHost}`} target="_blank" rel="noreferrer" className="mt-1 inline-flex items-center gap-1.5 font-mono text-sm text-brand-200 hover:underline">
                  {liveHost} <Icon name="external-link" size={13} />
                </a>
              )}
              {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}
              <div className="mt-4 rounded-xl border border-white/[0.06] bg-white/[0.02] p-4 text-left">
                <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">Go-live checklist</p>
                <ul className="space-y-1.5 text-sm text-slate-300">
                  <li className="flex items-center gap-2"><Icon name="check" size={14} className="text-emerald-300" /> Website created{appChoice !== "blank" ? " · app installing" : ""}</li>
                  <li className="flex items-center gap-2"><Icon name="link" size={14} className="text-slate-500" /> Connect a custom domain (Domain &amp; SSL)</li>
                  <li className="flex items-center gap-2"><Icon name="mail" size={14} className="text-slate-500" /> Set up email on this domain</li>
                  <li className="flex items-center gap-2"><Icon name="image" size={14} className="text-slate-500" /> Customize your site</li>
                </ul>
              </div>
              <div className="mt-5 flex justify-center gap-2">
                <button className="btn-secondary text-sm" onClick={() => onCreated()}>Back to console</button>
                <button className="btn-primary text-sm" onClick={() => onCreated(liveParam)}>Open website</button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function AppOption({
  active, onClick, title, sub, logo, icon,
}: {
  active: boolean; onClick: () => void; title: string; sub: string; logo?: string; icon?: IconName;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`flex w-full items-start gap-3 rounded-xl border px-3 py-2.5 text-left transition-colors ${active ? "border-brand-400/50 bg-brand-500/[0.08]" : "border-white/[0.06] hover:border-white/15"}`}
    >
      {logo ? <AppLogo family={logo} size={34} /> : (
        <span className="grid h-[34px] w-[34px] place-items-center rounded-lg border border-white/10 bg-white/[0.03] text-brand-200">
          <Icon name={icon ?? "grid"} size={17} />
        </span>
      )}
      <span className="min-w-0">
        <span className="block text-sm font-medium text-slate-100">{title}</span>
        <span className="block text-xs text-slate-500">{sub}</span>
      </span>
    </button>
  );
}

/* ------------------------------------------------------- bottom-row cards --- */

const LOG_LABELS: Record<string, string> = {
  PHP_SWITCH: "PHP version change", WORDPRESS_INSTALL: "WordPress install", APP_INSTALL: "App install",
  BACKUP: "Backup", RESTORE: "Restore", CREATE_SUBDOMAIN: "Subdomain created", DELETE_SUBDOMAIN: "Subdomain removed",
  CREATE_ADDON_DOMAIN: "Website created", DELETE_ADDON_DOMAIN: "Website removed", CREATE_CRON: "Cron job created",
  DELETE_CRON: "Cron job removed", ENSURE_DBMGR: "Database manager", APPLY_PLAN_LIMITS: "Plan update",
  SET_PRIMARY_DOMAIN: "Main address change", RESET_DB_PASSWORD: "Database password reset",
};

type LogRow = { id: string; kind: string; status: string; error: string | null; createdAt: string; updatedAt: string };

function useTaskLog(accountId: string) {
  const [rows, setRows] = useState<LogRow[] | null>(null);
  useEffect(() => {
    let stop = false;
    const load = () => listHostingTaskLog(accountId).then((r) => { if (!stop) setRows(r); }).catch(() => { if (!stop) setRows([]); });
    load();
    const t = setInterval(load, 8000);
    return () => { stop = true; clearInterval(t); };
  }, [accountId]);
  return rows;
}

function ActivityCard({ accountId, onSection }: { accountId: string; onSection: (s: string) => void }) {
  const rows = useTaskLog(accountId);
  return (
    <div className="card">
      <h3 className="mb-3 flex items-center gap-2 font-semibold">
        <Icon name="activity" size={16} className="text-brand-300" /> Recent activity
        <button type="button" onClick={() => onSection("activity")} className="ml-auto text-xs font-semibold text-brand-300 hover:underline">View all</button>
      </h3>
      {rows === null ? (
        <p className="text-sm text-slate-500">Loading…</p>
      ) : rows.length === 0 ? (
        <p className="text-sm text-slate-500">No activity yet.</p>
      ) : (
        <ul className="space-y-0">
          {rows.slice(0, 6).map((t) => (
            <li key={t.id} className="flex items-center gap-3 border-t border-white/[0.06] py-2 text-sm first:border-t-0">
              <span className="min-w-0 flex-1 truncate text-slate-300">{LOG_LABELS[t.kind] ?? t.kind}</span>
              <span className={`text-xs font-medium ${t.status === "FAILED" ? "text-red-300" : t.status === "DONE" ? "text-emerald-300" : "text-amber-300"}`}>{t.status.toLowerCase()}</span>
              <span className="shrink-0 text-xs text-slate-500">{timeAgo(new Date(t.createdAt))}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function PlanInfoCard({
  account, counts, siteCount, siteCap, onSection,
}: {
  account: HostingAccountView; counts: Counts | null; siteCount: number; siteCap: number; onSection: (s: string) => void;
}) {
  const diskGB = Math.round(account.diskQuotaMB / 1024);
  return (
    <div className="card">
      <h3 className="mb-3 flex items-center gap-2 font-semibold"><Icon name="server" size={16} className="text-brand-300" /> Plan &amp; usage</h3>
      <dl className="space-y-2 text-sm">
        <Row k="Plan" v={<Badge tone="brand">{account.planName}</Badge>} />
        <Row k="Status" v={<StatusDot status={account.status} />} />
        <Row k="Websites" v={`${siteCount} of ${siteCap}`} />
        <Row k="Storage" v={`${diskGB} GB${account.extraDiskGB > 0 ? ` (+${account.extraDiskGB} GB added)` : ""}`} />
        <Row k="Databases" v={account.maxDatabases > 0 ? `${counts?.dbs ?? 0} of ${account.maxDatabases}` : "Not on this plan"} />
        <Row k="Mailbox pool" v={counts?.emailCap != null ? `${counts.emailUsed} of ${counts.emailCap}` : "—"} />
        <Row k="PHP" v={<span className="font-mono text-xs">{account.phpVersion}</span>} />
        {account.expiresAt && <Row k="Renews" v={new Date(account.expiresAt).toISOString().slice(0, 10)} />}
      </dl>
      <button className="btn-secondary mt-4 w-full text-sm" onClick={() => onSection("settings")}>Manage plan &amp; upgrades</button>
    </div>
  );
}

function Row({ k, v }: { k: string; v: ReactNode }) {
  return (
    <div className="flex items-center justify-between gap-2 border-t border-white/[0.06] py-1.5 first:border-t-0">
      <dt className="text-slate-400">{k}</dt>
      <dd className="text-right font-medium">{v}</dd>
    </div>
  );
}

/** Real resource usage only — storage + inodes come off the account's usage sweep. */
function ResourceUsageCard({ account, counts }: { account: HostingAccountView; counts: Counts | null }) {
  const hasUsage = account.diskUsedMB != null || account.inodesUsed != null;
  if (!hasUsage) return null;
  const diskGB = Math.round(account.diskQuotaMB / 1024);
  const extraSites = counts ? counts.subs + counts.addons : 0;
  return (
    <div className="card">
      <h3 className="mb-4 flex items-center gap-2 font-semibold">
        <Icon name="cpu" size={16} className="text-brand-300" /> Resource usage
        {account.usageAt && <span className="text-xs font-normal text-slate-500">· measured {timeAgo(new Date(account.usageAt))}</span>}
      </h3>
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {account.diskUsedMB != null && (
          <QuotaTile label="Storage" primary={`${fmtBytes(account.diskUsedMB * 1024 * 1024)} of ${diskGB} GB`} bar={{ used: account.diskUsedMB, total: account.diskQuotaMB }} />
        )}
        {account.inodesUsed != null && (
          <QuotaTile label="Inodes (files)" primary={account.inodesUsed.toLocaleString()} note="Total files & folders" />
        )}
        <QuotaTile label="Extra sites" primary={`${extraSites} of ${account.maxSites}`} bar={{ used: extraSites, total: account.maxSites }} note="Subdomains + custom domains" />
        {account.maxDatabases > 0 && (
          <QuotaTile label="Databases" primary={`${counts?.dbs ?? 0} of ${account.maxDatabases}`} bar={{ used: counts?.dbs ?? 0, total: account.maxDatabases }} />
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------- connection card --- */

function ConnectionCard({ account }: { account: HostingAccountView }) {
  const [a, setA] = useState(account);
  const [sftpPw, setSftpPw] = useState<string | null>(null);
  const [recheckBusy, setRecheckBusy] = useState(false);
  const active = a.status === "ACTIVE";

  useEffect(() => {
    if (!active || a.sslActive) return;
    const t = setInterval(() => { getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {}); }, 15000);
    return () => clearInterval(t);
  }, [a.id, active, a.sslActive]);

  async function recheck() {
    setRecheckBusy(true);
    const r = await recheckHostingHealth(a.id);
    if (r.error) { alert(r.error); setRecheckBusy(false); return; }
    let tries = 0;
    const poll = setInterval(() => {
      tries++;
      getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {});
      if (tries >= 9) { clearInterval(poll); setRecheckBusy(false); }
    }, 5000);
  }
  async function reveal() {
    const res = await revealHostingSftpPassword(a.id);
    if (res.password) setSftpPw(res.password); else if (res.error) alert(res.error);
  }

  if (!active) return null;

  // Only show the "point your domain" helper when the plan's first website is a real
  // domain still settling — a free-subdomain plan has nothing to point.
  const showPoint = !a.isFreeSubdomain && !a.sslActive;
  if (!showPoint) return null;

  return (
    <div className="card">
      <div className="mb-3 flex items-center justify-between gap-2">
        <h3 className="flex items-center gap-2 font-semibold">
          <Icon name="globe" size={16} className="text-brand-300" /> Point your domain
        </h3>
        <button type="button" className="btn-secondary px-2.5 py-1 text-xs" disabled={recheckBusy} onClick={recheck}>
          {recheckBusy ? "Checking…" : "Go live"}
        </button>
      </div>
      <p className="mb-2 text-xs text-slate-400">
        Create an <span className="font-mono text-slate-200">A</span> record for <span className="font-mono text-slate-200">{a.primaryDomain}</span> → <span className="font-mono text-brand-200">{a.pointToA}</span>
        {a.pointToCname && <> (or a <span className="font-mono text-slate-200">CNAME</span> to <span className="font-mono text-slate-200">{a.pointToCname}</span>)</>}.
