        </div>
        <div className="ml-auto flex flex-wrap gap-2">
          <a href={site.sslActive ? `https://${site.hostname}` : `http://${site.hostname}`} target="_blank" rel="noreferrer" className="btn-secondary inline-flex items-center gap-1.5 text-sm"><Icon name="external-link" size={15} /> Visit</a>
