          <h3 className="mb-3 flex items-center gap-2 font-semibold"><Icon name="activity" size={16} className="text-brand-300" /> Recent activity</h3>
          {rows === null ? (
            <p className="text-sm text-slate-500">Loading…</p>
          ) : rows.length === 0 ? (
            <p className="text-sm text-slate-500">No activity yet.</p>
          ) : (
            <ul className="space-y-0">
              {rows.slice(0, 5).map((t) => (
                <li key={t.id} className="flex items-center gap-3 border-t border-white/[0.06] py-2 text-sm first:border-t-0">
                  <span className="min-w-0 flex-1 truncate text-slate-300">{LOG_LABELS[t.kind] ?? t.kind}</span>
                  <span className={`text-xs font-medium ${t.status === "FAILED" ? "text-red-300" : t.status === "DONE" ? "text-emerald-300" : "text-amber-300"}`}>{t.status.toLowerCase()}</span>
                  <span className="shrink-0 text-xs text-slate-500">{timeAgo(new Date(t.createdAt))}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>

      <div className="card">
        <h3 className="mb-3 font-semibold">Quick actions</h3>
        <div className="flex flex-col gap-2">
          <QuickAction icon="grid" label="Install / manage app" onClick={() => onSiteTab("app")} />
          <QuickAction icon="lock" label="Domain & SSL" onClick={() => onSiteTab("domains")} />
          <QuickAction icon="mail" label="Email on this site" onClick={() => onSiteTab("email")} />
          <QuickAction icon="folder" label="File manager" onClick={() => onSiteTab("files")} />
          <QuickAction icon="clock" label="Backups" onClick={() => onSiteTab("backups")} />
          <QuickAction icon="database" label="Databases" onClick={() => onSection("databases")} />
          {(site.kind === "subdomain" || site.kind === "addon") && (
            <QuickAction icon="trash" label="Delete website" tone="danger" onClick={() => onSiteTab("domains")} />
          )}
        </div>
      </div>
    </div>
  );
}

function QuickAction({ icon, label, onClick, tone }: { icon: IconName; label: string; onClick: () => void; tone?: "danger" }) {
  return (
    <button
      className={`inline-flex w-full items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-left text-sm transition-colors hover:border-brand-400/40 hover:bg-white/[0.04] ${tone === "danger" ? "text-red-300" : "text-slate-200"}`}
      onClick={onClick}
    >
      <Icon name={icon} size={16} /> {label}
    </button>
  );
}

function SiteAppTab({ account, site, onSitesChanged }: { account: HostingAccountView; site: HostingWebsiteView; onSitesChanged: () => void }) {
  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="mb-1 font-semibold">Install an app on {site.hostname}</h3>
        <p className="mb-4 text-sm text-slate-400">Install WordPress automatically, or pick another app from the catalog — it&apos;s installed into this website&apos;s document root (<span className="font-mono text-xs">{site.fileManagerPath}</span>).</p>
        <SiteInstaller account={account} site={site} onSitesChanged={onSitesChanged} />
      </div>
      <AppCredentials accountId={account.id} />
    </div>
  );
}

function SiteDomainsTab({
  account, site, onSection, onSitesChanged,
}: {
  account: HostingAccountView; site: HostingWebsiteView; onSection: (s: string) => void; onSitesChanged: () => void;
}) {
  const [busy, setBusy] = useState(false);
  async function promote() {
    if (!site.id) return;
    if (!confirm(`Make ${site.hostname} the main address for this plan? The old address keeps working as an alias.`)) return;
    setBusy(true);
    const r = await setPrimaryHostingDomain(account.id, site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }
  async function remove() {
    if (!site.id) return;
    if (!confirm(`Delete ${site.hostname}? Its files will be removed.`)) return;
    setBusy(true);
    const r = site.kind === "subdomain" ? await deleteSubdomain(site.id) : await deleteAddonDomain(site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }
  return (
    <div className="space-y-6">
      <div className="card max-w-2xl">
        <h3 className="mb-3 flex items-center gap-2 font-semibold"><Icon name="lock" size={16} className="text-brand-300" /> Domain &amp; SSL</h3>
        <dl className="space-y-2 text-sm">
          <Row k="Serving on" v={<span className="font-mono text-xs">{site.hostname}</span>} />
          <Row k="HTTPS" v={site.sslActive ? <span className="text-emerald-300">Active (auto-renew)</span> : <span className="text-amber-300">Issuing — automatic once DNS resolves</span>} />
          <Row k="Type" v={kindLabel(site)} />
        </dl>
        {!site.isFreeSubdomain && site.kind !== "primary" && (
          <p className="mt-3 text-xs text-slate-500">Point this domain with an <span className="font-mono text-slate-200">A</span> record to <span className="font-mono text-brand-200">{account.pointToA}</span>. HTTPS is issued automatically once it resolves.</p>
        )}
        <div className="mt-4 flex flex-wrap gap-2">
          {site.canSetPrimary && <button className="btn-secondary inline-flex items-center gap-1.5 text-sm" disabled={busy} onClick={promote}><Icon name="star" size={15} /> Make main address</button>}
          <button className="btn-secondary text-sm" onClick={() => onSection("domains")}>Connect / buy a domain</button>
        </div>
      </div>

      {(site.kind === "subdomain" || site.kind === "addon") && (
        <div className="card max-w-2xl border-red-500/20">
          <h3 className="mb-1 font-semibold text-red-300">Delete this website</h3>
          <p className="mb-3 text-sm text-slate-400">Removes {site.hostname} and its files from the plan. This can&apos;t be undone.</p>
          <button className="btn-danger inline-flex items-center gap-1.5 text-sm" disabled={busy} onClick={remove}><Icon name="trash" size={15} /> {busy ? "Deleting…" : `Delete ${site.hostname}`}</button>
        </div>
      )}
    </div>
  );
}

function SiteBackups({ accountId }: { accountId: string }) {
  return (
    <div className="space-y-4">
      <div className="card border-brand-500/15 bg-brand-500/[0.03] text-sm text-slate-400">
        Backups cover the whole plan — every website&apos;s files and databases in one restore point. Back up now or restore below.
      </div>
      <Backups accountId={accountId} />
    </div>
  );
}

function SiteDatabaseTab({ account }: { account: HostingAccountView }) {
  return (
    <div className="space-y-4">
      <div className="card border-white/[0.06] text-sm text-slate-400">
        Databases belong to the plan — an app on any website can connect to any of them. WordPress creates and wires its own database automatically; this is here for power users.
      </div>
      <DatabasesPanel accountId={account.id} username={account.username} maxDatabases={account.maxDatabases} />
    </div>
  );
}

function SitePhpTab({ account }: { account: HostingAccountView }) {
  return (
    <div className="card max-w-2xl">
      <h3 className="mb-1 font-semibold">PHP version</h3>
      <p className="mb-3 text-sm text-slate-400">The PHP runtime applies to every website on the plan. Changing it here changes it plan-wide.</p>
      <PhpSwitcher accountId={account.id} phpVersion={account.phpVersion} phpVersions={account.phpVersions} />
    </div>
  );
}

function StagingTab({ site }: { site: HostingWebsiteView }) {
  return (
    <div className="max-w-2xl">
      <ComingSoon
        feature="Staging site"
        note={`Spin up a private copy of ${site.hostname}, test changes safely, then push it live in one click. This is coming to your website's Advanced tools.`}
      />
    </div>
  );
}

